def _is_empty_string(value):
    return value == ""


def _is_none(value):
    return value is None


def _is_zero_divisor(value):
    return value == 0


def add(a, b):
    return a + b


def divide(a, b):
    if _is_zero_divisor(b):
        return None
    return a / b


def parse_int(value):
    if _is_empty_string(value):
        return None
    return int(value)


def normalize_name(name):
    if _is_none(name):
        return ""
    return name.strip().lower()


def clamp(value, low, high):
    return max(low, min(value, high))


def safe_divide(a, b, default=None):
    if _is_zero_divisor(b):
        return default
    return a / b
